19	bool MemSegment::deviceInfoReady{false};
20	int MemSegment::deviceId_{-1};
21	int MemSegment::logicDeviceId_{-1};
22	int MemSegment::devicePhyId_{-1};
23	uint32_t MemSegment::pid_{0};
24	uint32_t MemSegment::sdid_{0};
25	uint32_t MemSegment::serverId_{0};
26	uint32_t MemSegment::superPodId_{0};
27	AscendSocType MemSegment::socType_{AscendSocType::ASCEND_UNKNOWN};
28	std::string MemSegment::sysBoolId_{};
29	uint32_t MemSegment::bootIdHead_{0};
30	
31	MemSegmentPtr MemSegment::Create(const MemSegmentOptions& options, int entityId)
32	{
33	    if (options.rankId >= options.rankCnt) {
34	        SHM_LOG_ERROR("rank(" << options.rankId << ") but total " << options.rankCnt);
35	        return nullptr;
36	    }
37	
38	    auto ret = MemSegment::InitDeviceInfo();
39	    if (ret != ACLSHMEM_SUCCESS) {
40	        SHM_LOG_ERROR("MemSegment::InitDeviceInfo failed: " << ret);
41	        return nullptr;
42	    }
43	
44	    MemSegmentPtr tmpSeg;
45	    switch (options.segType) {
46	#ifdef HAS_ACLRT_MEM_FABRIC_HANDLE
47	        case HYBM_MST_HBM:
48	            if (options.userBufferHeapInput != nullptr) {
49	                tmpSeg = std::make_shared<AclMemSegmentDevice>(options, entityId);
50	                break;
51	            }
52	#ifdef USE_ACLRT_MEM_FABRIC_HANDLE
53	            tmpSeg = std::make_shared<AclMemSegmentDevice>(options, entityId);
54	#else
55	            if (socType_ == AscendSocType::ASCEND_950 || (HybmGetGvaVersion() == HYBM_GVA_V4)) {
56	                tmpSeg = std::make_shared<HybmVmmBasedSegment>(options, entityId);
57	            } else {
58	                tmpSeg = std::make_shared<MemSegmentDevice>(options, entityId);
59	            }
60	#endif
61	            break;
62	        case HYBM_MST_DRAM:
63	#ifdef USE_ACLRT_MEM_FABRIC_HANDLE
64	            tmpSeg = std::make_shared<AclMemSegmentDevice>(options, entityId);
65	#else
66	            SHM_LOG_ERROR("Not support HOST_SIDE malloc now.");
67	#endif
68	            break;
69	#else
70	        case HYBM_MST_HBM:
71	            if (socType_ == AscendSocType::ASCEND_950 || (HybmGetGvaVersion() == HYBM_GVA_V4)) {
72	                tmpSeg = std::make_shared<HybmVmmBasedSegment>(options, entityId);
73	            } else {
74	                tmpSeg = std::make_shared<MemSegmentDevice>(options, entityId);
75	            }
76	            break;
77	        case HYBM_MST_DRAM:
78	            SHM_LOG_ERROR("Not support HOST_SIDE malloc now.");
79	            break;
80	#endif
81	        default:
82	            SHM_LOG_ERROR("Invalid memory seg type " << int(options.segType));
83	    }
84	    return tmpSeg;
85	}
86	
87	Result MemSegment::GetDeviceInfo(uint32_t& sdId, uint32_t& serverId, uint32_t& superPodId)
88	{
89	    auto ret = MemSegment::InitDeviceInfo();
90	    if (ret != ACLSHMEM_SUCCESS) {
91	        SHM_LOG_ERROR("MemSegment::InitDeviceInfo failed: " << ret);
92	        return ret;
93	    }
94	
95	    sdId = sdid_;
96	    serverId = serverId_;
97	    superPodId = superPodId_;
98	    return ACLSHMEM_SUCCESS;
99	}
100	
101	bool MemSegment::CheckSdmaReaches(uint32_t rankId) const noexcept { return false; }
102	
103	Result MemSegment::InitDeviceInfo()
104	{
105	    if (deviceInfoReady) {
106	        return ACLSHMEM_SUCCESS;
107	    }
108	
109	    auto ret = DlAclApi::AclrtGetDevice(&deviceId_);
110	    if (ret != 0) {
111	        SHM_LOG_ERROR("get device id failed: " << ret);
112	        return ACLSHMEM_DL_FUNC_FAILED;
113	    }
114	
115	    ret = DlAclApi::RtGetLogicDevIdByUserDevId(deviceId_, &logicDeviceId_);
116	    if (ret != 0 || logicDeviceId_ < 0) {
117	        SHM_LOG_ERROR("Failed to get logic deviceId: " << deviceId_ << ", ret=" << ret);
118	        return ACLSHMEM_INNER_ERROR;
119	    }
120	
121	    ret = DlAclApi::AclrtGetPhyDevIdByUserDevId(deviceId_, &devicePhyId_);
122	    if (ret != 0 || devicePhyId_ < 0) {
123	        SHM_LOG_ERROR(
124	            "Failed to get phy deviceId: user=" << deviceId_ << ", logic=" << logicDeviceId_ << ", ret=" << ret);
125	        return ACLSHMEM_INNER_ERROR;
126	    }
127	
128	    ret = DlAclApi::RtDeviceGetBareTgid(&pid_);
129	    if (ret != ACLSHMEM_SUCCESS) {
130	        SHM_LOG_ERROR("get bare tgid failed: " << ret);
131	        return ACLSHMEM_DL_FUNC_FAILED;
132	    }
133	
134	    int64_t value = 0;
135	    ret = DlAclApi::RtGetDeviceInfo(deviceId_, 0, INFO_TYPE_SDID, &value);
136	    if (ret != ACLSHMEM_SUCCESS) {
137	        SHM_LOG_ERROR("get sdid failed: " << ret);
138	        return ACLSHMEM_DL_FUNC_FAILED;
139	    }
140	
141	    sdid_ = static_cast<uint32_t>(value);
142	    ret = DlAclApi::RtGetDeviceInfo(deviceId_, 0, INFO_TYPE_SERVER_ID, &value);
143	    if (ret != ACLSHMEM_SUCCESS) {
144	        SHM_LOG_ERROR("get server id failed: " << ret);
145	        return ACLSHMEM_DL_FUNC_FAILED;
146	    }
147	    serverId_ = static_cast<uint32_t>(value);
148	    SHM_LOG_DEBUG("local server=0x" << std::hex << serverId_);
149	
150	    ret = DlAclApi::RtGetDeviceInfo(deviceId_, 0, INFO_TYPE_SUPER_POD_ID, &value);
151	    if (ret != ACLSHMEM_SUCCESS) {
152	        SHM_LOG_ERROR("get super pod id failed: " << ret);
153	        return ACLSHMEM_DL_FUNC_FAILED;
154	    }
155	    socType_ = DlApi::GetAscendSocType();
156	
157	    FillSysBootIdInfo();
158	    superPodId_ = static_cast<uint32_t>(value);
159	    if (superPodId_ == invalidSuperPodId && serverId_ == GetInvalidServerIdBySocType(socType_)) {
160	        if (bootIdHead_ != 0) {
161	            serverId_ = bootIdHead_;
162	        } else {
163	            auto networks = utils::NetworkGetIpAddresses();
164	            if (networks.empty()) {
165	                SHM_LOG_ERROR("get local host ip address empty.");
166	                return ACLSHMEM_INNER_ERROR;
167	            }
168	            serverId_ = networks[0];
169	        }
170	    }
171	    SHM_LOG_DEBUG(
172	        "local sdid=0x" << std::hex << sdid_ << ", local server=0x" << std::hex << serverId_
173	                        << ", spid=" << superPodId_);
174	    deviceInfoReady = true;
175	    return ACLSHMEM_SUCCESS;
176	}
