178	void MemSegment::FillSysBootIdInfo() noexcept
179	{
180	    std::string bootIdPath("/proc/sys/kernel/random/boot_id");
181	    std::ifstream input(bootIdPath);
182	    input >> sysBoolId_;
183	
184	    std::stringstream ss(sysBoolId_);
185	    ss >> std::hex >> bootIdHead_;
186	    SHM_LOG_DEBUG("os-boot-id: " << sysBoolId_ << ", head u32: " << std::hex << bootIdHead_);
187	}
