202	bool MemSegment::IsSdmaAccessible(uint32_t superPodId, uint32_t serverId, uint32_t deviceId) noexcept
203	{
204	    if (serverId == serverId_) {
205	        return (socType_ != ASCEND_910B) || ((deviceId / ASC910B_CONN_RANKS) == (logicDeviceId_ / ASC910B_CONN_RANKS));
206	    }
207	
208	    if (superPodId == invalidSuperPodId || superPodId_ == invalidSuperPodId) {
209	        SHM_LOG_DEBUG("spid: " << superPodId << ", local: " << superPodId_ << " cannot reach.");
210	        return false;
211	    }
212	
213	    return superPodId == superPodId_;
214	}
