235	                "enable device access failed:" << ret << " local_user:" << deviceId_ << " local_phy:" << devicePhyId_
236	                                               << " remote_user:" << remoteUserId << " remote_phy:" << remotePhyId);
237	            return ACLSHMEM_DL_FUNC_FAILED;
