240	            "enable device access success (aclrt fallback) local_user:" << deviceId_
241	                                                                        << " remote_user:" << remoteUserId);
242	        return ACLSHMEM_SUCCESS;
243	    }
244	    if (ret != 0) {
245	        SHM_LOG_ERROR(
246	            "enable device access failed:" << ret << " local_user:" << deviceId_ << " local_phy:" << devicePhyId_
247	                                           << " remote_phy:" << remotePhyId);
248	        return ACLSHMEM_DL_FUNC_FAILED;
249	    }
